## 3. **PrizeBoost Component** (`components/PrizeBoost.tsx`)

```tsx
'use client';
import { useState } from 'react';

interface Props {
  entryId: string;
  entryTitle: string;
  photographerName: string;
  charityName?: string;
  currentBoost: number;
  boostCount: number;
  photoUrl?: string;
  userId?: string;
}

export default function PrizeBoost({
  entryId, entryTitle, photographerName, charityName = 'Local Charity',
  currentBoost = 0, boostCount = 0, photoUrl, userId
}: Props) {
  const [isLoading, setIsLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [selectedAmount, setSelectedAmount] = useState(10);
  const boostAmounts = [5, 10, 25, 50, 100];
  const isMostBoosted = currentBoost > 500 || boostCount > 100;

  const handleBoost = async (amount: number) => {
    setIsLoading(true);
    try {
      const res = await fetch('/api/boost/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ photoId: entryId, amount, charityName, boosterId: userId || null }),
      });
      const { url } = await res.json();
      if (url) window.location.href = url;
    } catch {
      alert('Boost failed. Try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="prize-boost space-y-3">
      <button
        onClick={() => setShowModal(true)}
        disabled={isLoading}
        className={`
          w-full py-4 px-6 rounded-xl font-bold text-lg shadow-lg transition-all
          ${isMostBoosted 
            ? 'bg-gradient-to-r from-orange-500 to-red-500 text-white shadow-orange-500/50' 
            : currentBoost > 0 
            ? 'bg-gradient-to-r from-emerald-500 to-teal-500 text-white shadow-emerald-500/30' 
            : 'bg-gradient-to-r from-blue-500 to-indigo-500 hover:from-blue-600 hover:to-indigo-600 text-white shadow-blue-500/25'
          }
        `}
      >
        <div className="flex items-center justify-between">
          <span>{isMostBoosted ? '🔥 MOST BOOSTED!' : '💰 Boost Prize!'}</span>
          {currentBoost > 0 && <span>${currentBoost.toLocaleString()}</span>}
          {boostCount > 0 && <span className="text-sm bg-white/20 px-3 py-1 rounded-full">{boostCount}+ boosters</span>}
        </div>
      </button>

      {showModal && (
        <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur flex items-center justify-center p-4"
             onClick={() => setShowModal(false)}>
          <div className="bg-white rounded-3xl p-8 max-w-md w-full max-h-[90vh] overflow-auto shadow-2xl border"
               onClick={e => e.stopPropagation()}>
            <h2 className="text-2xl font-bold text-center mb-8">Boost {photographerName}'s Photo</h2>

            <div className="grid grid-cols-3 gap-3 mb-8">
              {boostAmounts.map(amount => (
                <button
                  key={amount}
                  onClick={() => setSelectedAmount(amount)}
                  className={selectedAmount === amount 
                    ? 'bg-emerald-500 text-white p-4 rounded-xl font-bold shadow-lg' 
                    : 'bg-gray-100 hover:bg-gray-200 p-4 rounded-xl font-bold hover:scale-105'
                  }
                >
                  ${amount}
                </button>
              ))}
            </div>

            <div className="bg-emerald-50 p-6 rounded-2xl mb-8">
              <h3 className="font-bold text-lg mb-4 text-center">Your ${selectedAmount} breakdown:</h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between"><span>🥇 Prize Pool</span><span>${(selectedAmount * 0.75).toFixed(2)} (75%)</span></div>
                <div className="flex justify-between"><span>❤️ {charityName}</span><span>${(selectedAmount * 0.20).toFixed(2)} (20%)</span></div>
                <div className="flex justify-between font-medium border-t pt-2 mt-2"><span>💎 Platform</span><span>${(selectedAmount * 0.05).toFixed(2)} (5%)</span></div>
              </div>
            </div>

            <button
              onClick={() => handleBoost(selectedAmount)}
              disabled={isLoading}
              className="w-full bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-bold py-4 px-6 rounded-2xl shadow-xl hover:shadow-2xl mb-4"
            >
              {isLoading ? 'Processing...' : `Boost $${selectedAmount} Now!`}
            </button>

            <div className="text-xs text-gray-500 text-center">🔒 Secure via Stripe • No account needed</div>
          </div>
        </div>
      )}
    </div>
  );
}
```

